// =====================================================================
// Open Ticket Count Check & Load Balancer
// n8n-hubspot-support-ticket-auto-assignment-load-balancer
// dhRobin Systems · MIT License · Provided as-is, see DISCLAIMER.md
// ---------------------------------------------------------------------
// Mode: Run Once for All Items
// Input : HubSpot app-webhook event array OR HubSpot workflow-webhook object
// Output: one item per unique ticket, each carrying an `action`:
//   assign | dry_run_would_assign | skip_already_owned | skip_pipeline |
//   skip_event_type | skip_duplicate_event | no_capacity | rejected | error
// Only items with action === "assign" reach the HubSpot Owner Update node.
// =====================================================================

// ---------- 1. Configuration (environment variables, safe defaults) ----------
const ENV = (() => { try { return $env || {}; } catch (e) { return {}; } })();
const env = (key, fallback) => {
  const v = ENV[key];
  return v === undefined || v === null || String(v).trim() === '' ? fallback : String(v).trim();
};
const isOn  = (key) => env(key, 'true').toLowerCase() !== 'false';  // fail-safe: ON unless exactly "false"
const optIn = (key) => env(key, 'false').toLowerCase() === 'true';  // opt-in: OFF unless exactly "true"
const csv   = (key, fallback) => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);
const int   = (key, fallback) => { const n = parseInt(env(key, String(fallback)), 10); return Number.isFinite(n) ? n : fallback; };

const HUBSPOT_API_BASE = 'https://api.hubapi.com'; // fixed on purpose: the token is never sent anywhere else

const CONFIG = {
  DRY_RUN:               isOn('DRY_RUN'),
  SANDBOX_MODE:          isOn('SANDBOX_MODE'),
  AUTH_MODE:             env('WEBHOOK_AUTH_MODE', 'shared_secret').toLowerCase(), // shared_secret | hubspot_v3 | none
  WEBHOOK_SHARED_SECRET: env('WEBHOOK_SHARED_SECRET', ''),
  WEBHOOK_TOKEN_HEADER:  env('WEBHOOK_TOKEN_HEADER', 'x-webhook-token').toLowerCase(),
  HUBSPOT_CLIENT_SECRET: env('HUBSPOT_CLIENT_SECRET', ''),
  PUBLIC_WEBHOOK_URL:    env('PUBLIC_WEBHOOK_URL', ''),
  HUBSPOT_ACCESS_TOKEN:  env('HUBSPOT_ACCESS_TOKEN', ''),
  CLOSED_STAGE_IDS:      csv('CLOSED_STAGE_IDS', '4'),
  OPEN_STAGE_IDS:        csv('OPEN_STAGE_IDS', ''),
  ALLOWED_PIPELINE_IDS:  csv('ALLOWED_PIPELINE_IDS', ''),
  ACCEPTED_EVENT_TYPES:  csv('ACCEPTED_EVENT_TYPES', 'ticket.creation'),
  REASSIGN_IF_OWNED:     optIn('REASSIGN_IF_OWNED'),
  FALLBACK_OWNER_ID:     env('FALLBACK_OWNER_ID', ''),
  DEFAULT_CAPACITY:      Math.max(1, int('DEFAULT_AGENT_CAPACITY', 20)),
  SEARCH_DELAY_MS:       Math.max(0, int('SEARCH_DELAY_MS', 250)),
};

// Live writes are only possible when BOTH flags are off.
const EFFECTIVE_DRY_RUN = CONFIG.DRY_RUN || CONFIG.SANDBOX_MODE;

// ---------- 2. Agent pool (placeholders only — replace via AGENT_POOL_JSON) ----------
const PLACEHOLDER_AGENT_POOL = [
  { ownerId: 'OWNER_ID_AGENT_A', name: 'Agent A (placeholder)', capacity: 15, active: true, priorities: ['LOW', 'MEDIUM', 'HIGH', 'URGENT'], mockOpenTickets: 7 },
  { ownerId: 'OWNER_ID_AGENT_B', name: 'Agent B (placeholder)', capacity: 15, active: true, priorities: ['LOW', 'MEDIUM', 'HIGH', 'URGENT'], mockOpenTickets: 3 },
  { ownerId: 'OWNER_ID_AGENT_C', name: 'Agent C (placeholder)', capacity: 10, active: true, priorities: ['LOW', 'MEDIUM'],                   mockOpenTickets: 4 },
  { ownerId: 'OWNER_ID_AGENT_D', name: 'Agent D (placeholder, on leave)', capacity: 15, active: false, priorities: null,                   mockOpenTickets: 0 },
];

function normalizeAgent(a, i) {
  const ownerId = String((a && (a.ownerId ?? a.owner_id)) ?? '').trim();
  if (!ownerId) throw new Error(`Agent pool entry ${i} is missing "ownerId".`);
  return {
    ownerId,
    name: String(a.name || `Agent ${i + 1}`),
    capacity: Math.max(1, Number(a.capacity) || CONFIG.DEFAULT_CAPACITY),
    active: a.active !== false,
    priorities: Array.isArray(a.priorities) && a.priorities.length ? a.priorities.map((p) => String(p).toUpperCase()) : null, // null = all priorities
    mockOpenTickets: Math.max(0, Number(a.mockOpenTickets) || 0),
  };
}

function loadAgentPool() {
  const raw = env('AGENT_POOL_JSON', '');
  if (!raw) return { pool: PLACEHOLDER_AGENT_POOL.map(normalizeAgent), source: 'placeholder' };
  let parsed;
  try { parsed = JSON.parse(raw); } catch (e) { throw new Error('AGENT_POOL_JSON is not valid JSON.'); }
  if (!Array.isArray(parsed) || parsed.length === 0) throw new Error('AGENT_POOL_JSON must be a non-empty JSON array.');
  const pool = parsed.map(normalizeAgent);
  const ids = new Set();
  for (const a of pool) { if (ids.has(a.ownerId)) throw new Error(`Duplicate ownerId in AGENT_POOL_JSON: ${a.ownerId}`); ids.add(a.ownerId); }
  return { pool, source: 'env' };
}

const { pool: AGENT_POOL, source: AGENT_POOL_SOURCE } = loadAgentPool();

// ---------- 3. Live-mode guard rails ----------
const looksPlaceholder = (v) => /YOUR_|PLACEHOLDER|CHANGE_ME|REPLACE_/i.test(String(v || ''));
if (!CONFIG.SANDBOX_MODE) {
  if (!CONFIG.HUBSPOT_ACCESS_TOKEN || looksPlaceholder(CONFIG.HUBSPOT_ACCESS_TOKEN)) {
    throw new Error('SANDBOX_MODE=false requires a real HUBSPOT_ACCESS_TOKEN environment variable.');
  }
  if (AGENT_POOL_SOURCE === 'placeholder' || AGENT_POOL.some((a) => !/^\d+$/.test(a.ownerId))) {
    throw new Error('SANDBOX_MODE=false requires AGENT_POOL_JSON with numeric HubSpot owner IDs.');
  }
  if (CONFIG.FALLBACK_OWNER_ID && !/^\d+$/.test(CONFIG.FALLBACK_OWNER_ID)) {
    throw new Error('FALLBACK_OWNER_ID must be a numeric HubSpot owner ID.');
  }
}

// ---------- 4. Helpers ----------
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const lowerKeys = (obj) => Object.fromEntries(Object.entries(obj || {}).map(([k, v]) => [String(k).toLowerCase(), v]));

function safeEqual(a, b) { // constant-time string comparison
  a = String(a || ''); b = String(b || '');
  let diff = a.length ^ b.length;
  const n = Math.max(a.length, b.length);
  for (let i = 0; i < n; i++) diff |= (a.charCodeAt(i) || 0) ^ (b.charCodeAt(i) || 0);
  return diff === 0 && a.length > 0;
}

function redact(text) {
  return String(text || '')
    .replace(/Bearer\s+[A-Za-z0-9\-_.=]+/gi, 'Bearer [REDACTED]')
    .replace(/pat-[a-z0-9]{2,}-[A-Za-z0-9-]+/gi, '[REDACTED_TOKEN]')
    .slice(0, 200);
}

function sanitizeError(err) {
  const status = err?.httpCode || err?.statusCode || err?.response?.status || err?.cause?.status || null;
  return { status: status ? Number(status) : null, message: redact(err?.message || 'Unknown error') };
}

function hashString(s) {
  let h = 0;
  for (const ch of String(s)) h = (h * 31 + ch.charCodeAt(0)) >>> 0;
  return h;
}

const helpers = this.helpers;
async function hubspot(method, path, body) {
  if (!helpers || typeof helpers.httpRequest !== 'function') {
    throw new Error('this.helpers.httpRequest is not available in this n8n version.');
  }
  const options = {
    method,
    url: `${HUBSPOT_API_BASE}${path}`,
    headers: { Authorization: `Bearer ${CONFIG.HUBSPOT_ACCESS_TOKEN}`, 'Content-Type': 'application/json' },
    json: true,
    timeout: 10000,
  };
  if (body) options.body = body;
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      return await helpers.httpRequest(options);
    } catch (err) {
      const safe = sanitizeError(err);
      if ((safe.status === 429 || (safe.status && safe.status >= 500)) && attempt < 3) { await sleep(1000 * attempt); continue; }
      const wrapped = new Error(`HubSpot ${method} ${path.split('?')[0]} failed`);
      wrapped.safe = safe;
      throw wrapped;
    }
  }
}

// ---------- 5. Webhook authentication ----------
function verifyHubSpotV3(item, headers) {
  if (!CONFIG.HUBSPOT_CLIENT_SECRET || looksPlaceholder(CONFIG.HUBSPOT_CLIENT_SECRET)) return { ok: false, reason: 'hubspot_client_secret_not_configured' };
  let crypto;
  try { crypto = require('crypto'); } catch (e) { return { ok: false, reason: 'crypto_module_not_allowed_set_NODE_FUNCTION_ALLOW_BUILTIN' }; }
  const signature = headers['x-hubspot-signature-v3'];
  const timestamp = headers['x-hubspot-request-timestamp'];
  if (!signature || !timestamp) return { ok: false, reason: 'signature_headers_missing' };
  if (Math.abs(Date.now() - Number(timestamp)) > 5 * 60 * 1000) return { ok: false, reason: 'signature_timestamp_out_of_window' };
  const uri = CONFIG.PUBLIC_WEBHOOK_URL || item.webhookUrl || '';
  const rawBody = typeof item.body === 'string' ? item.body : JSON.stringify(item.body ?? '');
  const expected = crypto.createHmac('sha256', CONFIG.HUBSPOT_CLIENT_SECRET).update(`POST${uri}${rawBody}${timestamp}`, 'utf8').digest('base64');
  return safeEqual(expected, signature) ? { ok: true, reason: 'hubspot_v3_signature_valid' } : { ok: false, reason: 'hubspot_v3_signature_mismatch' };
}

function authenticate(item) {
  const headers = lowerKeys(item.headers);
  switch (CONFIG.AUTH_MODE) {
    case 'none':
      return CONFIG.SANDBOX_MODE ? { ok: true, reason: 'auth_disabled_sandbox_only' } : { ok: false, reason: 'auth_mode_none_not_allowed_live' };
    case 'hubspot_v3':
      return verifyHubSpotV3(item, headers);
    case 'shared_secret':
    default: {
      const secret = CONFIG.WEBHOOK_SHARED_SECRET;
      if (!secret || looksPlaceholder(secret)) return { ok: false, reason: 'shared_secret_not_configured' };
      const provided = headers[CONFIG.WEBHOOK_TOKEN_HEADER] || (item.query && item.query.token) || '';
      return safeEqual(secret, provided) ? { ok: true, reason: 'shared_secret_valid' } : { ok: false, reason: 'shared_secret_mismatch' };
    }
  }
}

// ---------- 6. Payload normalisation (app webhooks + workflow webhooks) ----------
function extractEvents(item) {
  const body = item.body !== undefined ? item.body : item;
  const list = Array.isArray(body) ? body : [body];
  const events = [];
  for (const ev of list) {
    if (!ev || typeof ev !== 'object') continue;
    const props = ev.properties && typeof ev.properties === 'object' ? ev.properties : {};
    const pv = (k) => { const v = props[k]; return v && typeof v === 'object' && 'value' in v ? v.value : v; };
    const ticketId = ev.objectId ?? ev.ticketId ?? ev.hs_object_id ?? pv('hs_object_id');
    const priority = pv('hs_ticket_priority') ?? ev.hs_ticket_priority ?? ev.priority ?? null;
    events.push({
      ticketId: ticketId !== undefined && ticketId !== null ? String(ticketId).trim() : null,
      eventId: ev.eventId !== undefined ? String(ev.eventId) : null,
      subscriptionType: ev.subscriptionType || null,
      source: ev.subscriptionType ? 'app_webhook' : 'workflow_webhook',
      priority: priority ? String(priority).toUpperCase() : null,
      pipeline: pv('hs_pipeline') ?? ev.hs_pipeline ?? null,
      existingOwnerId: pv('hubspot_owner_id') ?? ev.hubspot_owner_id ?? null,
    });
  }
  return events;
}

// ---------- 7. Open ticket count check (once per execution) ----------
async function buildLoadSnapshot() {
  const snapshot = [];
  for (const agent of AGENT_POOL) {
    const row = { ...agent, openTickets: null, countSource: null, countError: null };
    if (!agent.active) { row.countSource = 'skipped_inactive'; snapshot.push(row); continue; }
    if (CONFIG.SANDBOX_MODE) { row.openTickets = agent.mockOpenTickets; row.countSource = 'mock'; snapshot.push(row); continue; }
    try {
      const filters = [{ propertyName: 'hubspot_owner_id', operator: 'EQ', value: agent.ownerId }];
      if (CONFIG.OPEN_STAGE_IDS.length) filters.push({ propertyName: 'hs_pipeline_stage', operator: 'IN', values: CONFIG.OPEN_STAGE_IDS });
      else if (CONFIG.CLOSED_STAGE_IDS.length) filters.push({ propertyName: 'hs_pipeline_stage', operator: 'NOT_IN', values: CONFIG.CLOSED_STAGE_IDS });
      const res = await hubspot('POST', '/crm/v3/objects/tickets/search', { filterGroups: [{ filters }], properties: ['hs_object_id'], limit: 1 });
      row.openTickets = Number(res?.total ?? 0);
      row.countSource = 'hubspot_search';
    } catch (err) {
      row.countError = err.safe || sanitizeError(err);
      row.countSource = 'error'; // agent is excluded from this run rather than guessed at
    }
    snapshot.push(row);
    if (CONFIG.SEARCH_DELAY_MS) await sleep(CONFIG.SEARCH_DELAY_MS); // respect HubSpot search rate limits
  }
  return snapshot;
}

const staticData = (() => { try { return $getWorkflowStaticData('global'); } catch (e) { return {}; } })();
staticData.lastAssignedAt = staticData.lastAssignedAt || {};

// ---------- 8. Load balancer ----------
// Lowest utilisation (open / capacity) wins; ties go to the lower raw count,
// then the agent assigned least recently, then a deterministic per-ticket rotation.
function selectAgent(ticketId, priority, snapshot) {
  const withCapacity = snapshot.filter((r) => r.active && Number.isFinite(r.openTickets) && r.openTickets < r.capacity);
  let candidates = withCapacity.filter((r) => !r.priorities || !priority || r.priorities.includes(priority));
  let note = null;
  if (!candidates.length && withCapacity.length) { candidates = withCapacity; note = 'no_priority_match_fallback_to_any_agent_with_capacity'; }
  if (!candidates.length) return null;
  const rotation = hashString(ticketId);
  const last = (id) => staticData.lastAssignedAt[id] || 0;
  candidates.sort((a, b) =>
    (a.openTickets / a.capacity) - (b.openTickets / b.capacity) ||
    a.openTickets - b.openTickets ||
    last(a.ownerId) - last(b.ownerId) ||
    ((hashString(a.ownerId) + rotation) % 997) - ((hashString(b.ownerId) + rotation) % 997)
  );
  return { agent: candidates[0], note };
}

const viewSnapshot = (snapshot) => snapshot.map((r) => ({
  ownerId: r.ownerId,
  name: r.name,
  active: r.active,
  openTickets: r.openTickets,
  capacity: r.capacity,
  utilization: Number.isFinite(r.openTickets) ? Math.round((r.openTickets / r.capacity) * 1000) / 1000 : null,
  countSource: r.countSource,
  countError: r.countError,
}));

// ---------- 9. Main ----------
const inputs = $input.all();
const results = [];
const evaluatedAt = new Date().toISOString();
const mode = { dryRun: EFFECTIVE_DRY_RUN, sandbox: CONFIG.SANDBOX_MODE, agentPoolSource: AGENT_POOL_SOURCE };
const seen = new Set();
let loadSnapshot = null;

for (let i = 0; i < inputs.length; i++) {
  const item = inputs[i].json || {};
  const auth = authenticate(item);

  if (!auth.ok && !CONFIG.SANDBOX_MODE) {
    // Sanitised: no payload, no headers, no reason detail beyond a generic code.
    results.push({ json: { action: 'rejected', reason: 'unauthenticated_request', evaluatedAt, mode }, pairedItem: { item: i } });
    continue;
  }

  const events = extractEvents(item);
  if (!events.length) {
    results.push({ json: { action: 'error', reason: 'no_events_in_payload', evaluatedAt, mode, authCheck: auth.reason }, pairedItem: { item: i } });
    continue;
  }

  for (const ev of events) {
    const base = {
      ticketId: ev.ticketId,
      eventId: ev.eventId,
      source: ev.source,
      subscriptionType: ev.subscriptionType,
      priority: ev.priority,
      pipeline: ev.pipeline,
      evaluatedAt,
      mode,
      authCheck: auth.reason,
      correlationId: `${ev.ticketId || 'unknown'}-${Date.now()}`,
    };
    const emit = (action, extra = {}) => results.push({
      json: { ...base, action, selectedOwnerId: null, selectedAgentName: null, ...extra },
      pairedItem: { item: i },
    });

    const validId = ev.ticketId && /^[A-Za-z0-9_-]{1,40}$/.test(ev.ticketId) && (CONFIG.SANDBOX_MODE || /^\d+$/.test(ev.ticketId));
    if (!validId) { emit('error', { ticketId: null, reason: 'invalid_or_missing_ticket_id' }); continue; }
    if (seen.has(ev.ticketId)) { emit('skip_duplicate_event', { reason: 'ticket_already_processed_in_this_batch' }); continue; }
    seen.add(ev.ticketId);

    if (ev.subscriptionType && !CONFIG.ACCEPTED_EVENT_TYPES.includes(ev.subscriptionType)) {
      emit('skip_event_type', { reason: `event_type_not_accepted:${ev.subscriptionType}` }); continue;
    }

    // Current ticket state (live reads only). Doubles as the idempotency check for HubSpot retries.
    let ownerId = ev.existingOwnerId;
    if (!CONFIG.SANDBOX_MODE) {
      try {
        const t = await hubspot('GET', `/crm/v3/objects/tickets/${encodeURIComponent(ev.ticketId)}?properties=hubspot_owner_id,hs_pipeline,hs_pipeline_stage,hs_ticket_priority`);
        const p = (t && t.properties) || {};
        ownerId = p.hubspot_owner_id || null;
        base.pipeline = p.hs_pipeline || null;
        base.priority = p.hs_ticket_priority ? String(p.hs_ticket_priority).toUpperCase() : null;
      } catch (err) {
        emit('error', { reason: 'ticket_lookup_failed', error: err.safe || sanitizeError(err) }); continue;
      }
    }

    if (ownerId && !CONFIG.REASSIGN_IF_OWNED) { emit('skip_already_owned', { reason: 'ticket_already_has_owner', existingOwnerId: String(ownerId) }); continue; }
    if (CONFIG.ALLOWED_PIPELINE_IDS.length && !CONFIG.ALLOWED_PIPELINE_IDS.includes(String(base.pipeline))) {
      emit('skip_pipeline', { reason: 'pipeline_not_in_ALLOWED_PIPELINE_IDS' }); continue;
    }

    if (!loadSnapshot) loadSnapshot = await buildLoadSnapshot();
    const snapshotView = viewSnapshot(loadSnapshot);
    const pick = selectAgent(ev.ticketId, base.priority, loadSnapshot);

    if (!pick) {
      if (CONFIG.FALLBACK_OWNER_ID) {
        emit(EFFECTIVE_DRY_RUN ? 'dry_run_would_assign' : 'assign', {
          selectedOwnerId: CONFIG.FALLBACK_OWNER_ID, selectedAgentName: 'Fallback owner',
          reason: 'all_agents_at_capacity_fallback_owner', loadSnapshot: snapshotView,
        });
      } else {
        emit('no_capacity', { reason: 'all_agents_at_capacity_or_unavailable', loadSnapshot: snapshotView });
      }
      continue;
    }

    const agent = pick.agent;
    const loadBefore = agent.openTickets;
    agent.openTickets += 1; // batch-aware: later tickets in this execution see the new load
    if (!EFFECTIVE_DRY_RUN) staticData.lastAssignedAt[agent.ownerId] = Date.now();

    emit(EFFECTIVE_DRY_RUN ? 'dry_run_would_assign' : 'assign', {
      selectedOwnerId: agent.ownerId,
      selectedAgentName: agent.name,
      selectedAgentLoadBefore: loadBefore,
      selectedAgentCapacity: agent.capacity,
      reason: pick.note || 'lowest_utilization',
      loadSnapshot: snapshotView,
    });
  }
}

return results;

// Audit Log — compact, secret-free record of a confirmed assignment.
// Mode: Run Once for Each Item
const decision = $('Open Ticket Count Check & Load Balancer').item.json;
const res = $json || {};

return {
  json: {
    status: 'assigned',
    ticketId: decision.ticketId,
    ownerId: decision.selectedOwnerId,
    agentName: decision.selectedAgentName,
    reason: decision.reason,
    agentLoadBefore: decision.selectedAgentLoadBefore ?? null,
    agentCapacity: decision.selectedAgentCapacity ?? null,
    hubspotConfirmedOwnerId: (res.properties && res.properties.hubspot_owner_id) || null,
    hubspotUpdatedAt: res.updatedAt || null,
    correlationId: decision.correlationId,
    loggedAt: new Date().toISOString(),
  },
};

// Sanitized Error Handler — strips tokens and request internals from HubSpot errors.
// Mode: Run Once for Each Item
const decision = $('Open Ticket Count Check & Load Balancer').item.json;
const err = $json.error || {};
const raw = typeof err === 'string' ? err : (err.message || err.description || 'HubSpot owner update failed');
const message = String(raw)
  .replace(/Bearer\s+[A-Za-z0-9\-_.=]+/gi, 'Bearer [REDACTED]')
  .replace(/pat-[a-z0-9]{2,}-[A-Za-z0-9-]+/gi, '[REDACTED_TOKEN]')
  .slice(0, 200);
const httpStatus = Number(err.httpCode || err.status || err.statusCode) || null;

const HINTS = {
  400: 'HubSpot rejected the owner ID. Confirm the owner exists in this portal and can own tickets.',
  401: 'Access token invalid or expired. Rotate HUBSPOT_ACCESS_TOKEN.',
  403: 'Token is missing the "tickets" scope.',
  404: 'Ticket not found. It may have been deleted or belongs to another portal.',
  429: 'HubSpot rate limit hit. Increase SEARCH_DELAY_MS or reduce concurrency.',
};

return {
  json: {
    status: 'assignment_failed',
    ticketId: decision.ticketId,
    intendedOwnerId: decision.selectedOwnerId,
    httpStatus,
    message,
    hint: HINTS[httpStatus] || 'Check the n8n execution log and HubSpot API status.',
    correlationId: decision.correlationId,
    loggedAt: new Date().toISOString(),
  },
};
